function H({registerIndicator:R,nulls:p}){R({id:"oa-rvgi",name:"Relative Vigor Index (RVGI)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1}],plots:[{key:"rvgi",type:"line",title:"RVGI",style:{color:"#ffeb3b",lineWidth:2}},{key:"signal",type:"line",title:"Signal",style:{color:"#00bcd4",lineWidth:1}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(n,V){const l=Math.max(1,Math.floor(Number(V.period)||10)),o=n.length,y=new Array(o).fill(NaN),v=new Array(o).fill(NaN),t=(e,f)=>{if(e<0||e>=o)return 0;const c=n[e][f];return Number.isFinite(c)?c:0},w=new Array(l).fill(NaN),b=new Array(l).fill(NaN);let i=0,u=0,x=0,s=0,m=0,F=0,d=0,h=0,k=0;for(let e=0;e<o;e++){const f=n[e].close-n[e].open,c=t(e-1,"close")-t(e-1,"open"),D=t(e-2,"close")-t(e-2,"open");let r=(t(e-3,"close")-t(e-3,"open")+2*D+2*c+f)/6;Number.isFinite(r)||(r=0);const I=n[e].high-n[e].low,O=t(e-1,"high")-t(e-1,"low"),S=t(e-2,"high")-t(e-2,"low");let a=(t(e-3,"high")-t(e-3,"low")+2*S+2*O+I)/6;Number.isFinite(a)||(a=0);const A=w[i];Number.isFinite(A)?u-=A:x+=1,u+=r,w[i]=r,i=(i+1)%l;const B=u/Math.max(1,x),M=b[s];Number.isFinite(M)?m-=M:F+=1,m+=a,b[s]=a,s=(s+1)%l;const N=m/Math.max(1,F),g=!Number.isFinite(N)||N===0?0:B/N;v[e]=(k+2*h+2*d+g)/6,y[e]=g,k=h,h=d,d=g}return{rvgi:p(y),signal:p(v)}}})}export{H as default};
